function ModalBox({open,onClose,title,children,footer}){return <ModalOverlay isOpen={open} onOpenChange={v=>!v&&onClose()} isDismissable className="ui-modal-overlay"><Modal className="ui-modal"><Dialog className="ui-dialog" aria-label={title}><div className="dialog-heading"><h2>{title}</h2><IconButton name="revoke" label="Закрити / Close" onPress={onClose}/></div>{children}{footer&&<div className="dialog-actions">{footer}</div>}</Dialog></Modal></ModalOverlay>}
function Field({label,value,onChange,onBlur,error,textarea=false,type='text',hint,name}){const Tag=textarea?'textarea':'input',id=React.useId();return <div className="ui-field"><label htmlFor={id}>{label}</label><Tag id={id} name={name} type={textarea?undefined:type} className={textarea?'ui-textarea':'ui-input'} value={value} onChange={e=>onChange(e.target.value)} onBlur={onBlur} aria-invalid={!!error} aria-describedby={error?id+'-error':hint?id+'-hint':undefined}/>{hint&&<span className="ui-description" id={id+'-hint'}>{hint}</span>}{error&&<span className="ui-field-error" id={id+'-error'}>{error}</span>}</div>}
function Empty({icon='search',title,description,action}){return <div className="ui-state"><span className="ui-icon-tile"><Icon name={icon}/></span><h3>{title}</h3><p>{description}</p>{action}</div>}
function PageHeader({eyebrow,title,description,actions}){return <header className="admin-page-header"><div><span className="admin-eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div><div className="admin-page-actions">{actions}</div></header>}
function langSortLabel(t){return t("All")==="Усі"?"Сортування":"Sort"}
export function DataTable({rows,columns,actions,t,caption,emptyAction}){const[sort,setSort]=useState({key:columns[0].key,dir:'asc'}),[page,setPage]=useState(0);useEffect(()=>setPage(0),[rows.length]);const sorted=[...rows].sort((a,b)=>{const av=a[sort.key],bv=b[sort.key];const x=typeof av==='number'?av-bv:String(av??'').localeCompare(String(bv??''));return sort.dir==='asc'?x:-x}),pages=Math.max(1,Math.ceil(rows.length/5)),actual=Math.min(page,pages-1),slice=sorted.slice(actual*5,actual*5+5);return <section className="ui-card admin-table-card">{!rows.length?<Empty title={t('No results')} description={t('Change your search or clear the filters.')} action={emptyAction}/>:<><div className="table-mobile-sort"><label>{t("Updated")} / {langSortLabel(t)}<select className="ui-input" aria-label={langSortLabel(t)} value={sort.key} onChange={e=>{setSort({...sort,key:e.target.value});setPage(0)}}>{columns.map(c=><option key={c.key} value={c.key}>{t(c.label)}</option>)}</select></label><IconButton name={sort.dir==="asc"?"up":"down"} label={t("All")==="Усі"?"Змінити напрям сортування":"Reverse sort order"} onPress={()=>setSort({...sort,dir:sort.dir==="asc"?"desc":"asc"})}/></div><div className="ui-table-scroll"><table className="ui-table"><caption className="sr-only">{caption}</caption><thead><tr>{columns.map(c=><th key={c.key} scope="col" className={c.numeric?'is-numeric':''} aria-sort={sort.key===c.key?(sort.dir==='asc'?'ascending':'descending'):'none'}><Button className="table-sort" onPress={()=>{setSort({key:c.key,dir:sort.key===c.key&&sort.dir==='asc'?'desc':'asc'});setPage(0)}}>{t(c.label)}<span className={sort.key===c.key?'sort-current':'sort-idle'}><Icon name={sort.key===c.key&&sort.dir==='desc'?'down':'up'}/></span></Button></th>)}<th scope="col" className="admin-table-actions">{t('Actions')}</th></tr></thead><tbody>{slice.map(row=><tr key={row.id}>{columns.map(c=><td key={c.key} data-label={t(c.label)} className={(c.numeric?'is-numeric ':'')+(c.key===columns[0].key?'admin-table-identifier':'')}>{c.render?c.render(row):row[c.key]}</td>)}<td className="admin-table-actions" data-label={t('Actions')}><div className="table-action-group">{actions(row)}</div></td></tr>)}</tbody></table></div><div className="ui-pagination"><span>{actual*5+1}–{Math.min((actual+1)*5,rows.length)} / {rows.length} <span className="pagination-caption">{caption}</span></span><div><IconButton name="back" label={t('Previous page')} unavailable={actual===0} onPress={()=>setPage(Math.max(0,actual-1))}/><span className="page-count" aria-live="polite">{actual+1} / {pages}</span><IconButton name="arrow" label={t('Next page')} unavailable={actual===pages-1} onPress={()=>setPage(Math.min(pages-1,actual+1))}/></div></div></>}</section>}
function RichText({html,onChange,t,task=false}){const[linkOpen,setLinkOpen]=useState(false),[url,setUrl]=useState('');const editor=useEditor({extensions:[StarterKit.configure({link:{openOnClick:false}})],content:html,onUpdate:({editor})=>onChange(editor.getHTML()),editorProps:{attributes:{class:'lesson-prose',role:'textbox','aria-multiline':'true','aria-label':t(task?'Task':'Text')}}});if(!editor)return null;const commands=[['B','Bold','bold',()=>editor.chain().focus().toggleBold().run()],['I','Italic','italic',()=>editor.chain().focus().toggleItalic().run()],['H2','Heading 2','heading',()=>editor.chain().focus().toggleHeading({level:2}).run(),{level:2}],['H3','Heading 3','heading',()=>editor.chain().focus().toggleHeading({level:3}).run(),{level:3}],['list','Bullet list','bulletList',()=>editor.chain().focus().toggleBulletList().run()],['ordered','Ordered list','orderedList',()=>editor.chain().focus().toggleOrderedList().run()]];return <><div className="lesson-editor-toolbar" aria-label={t('Editor')}>{commands.map(([label,title,key,fn,attrs],i)=><TooltipTrigger key={title} delay={250}><Button aria-label={t(title)} aria-pressed={editor.isActive(key,attrs)} className={'ui-button toolbar-button '+(i===2||i===4?'toolbar-group-start':'')} onPress={fn}>{icons[label]?<Icon name={label}/>:<span className={label==='I'?'italic':''}>{label}</span>}</Button><Tooltip className="ui-tooltip">{t(title)}</Tooltip></TooltipTrigger>)}<IconButton name="link" label={t('Add link')} pressed={editor.isActive('link')} onPress={()=>{setUrl(editor.getAttributes('link').href||'');setLinkOpen(true)}}/><span className="toolbar-caption">{t(task?'Task':'Text')}</span></div><EditorContent className={'lesson-editor-input '+(task?'lesson-document-task':'')} editor={editor}/><ModalBox open={linkOpen} onClose={()=>setLinkOpen(false)} title={t('Add link')} footer={<><Button className="ui-button ui-button--secondary" onPress={()=>setLinkOpen(false)}>{t('Cancel')}</Button><Button className="ui-button ui-button--primary" onPress={()=>{if(/^https?:\/\//i.test(url)){editor.chain().focus().extendMarkRange('link').setLink({href:url}).run();setLinkOpen(false)}else if(!url){editor.chain().focus().unsetLink().run();setLinkOpen(false)}}}>{t('Confirm')}</Button></>}><Field label="URL" value={url} onChange={setUrl} type="url" hint="https://…"/></ModalBox></>}
const sectionNames={text:'Text',video:'Video',image:'Image',row:'Columns',task:'Task'};
const lessonInitial=[{id:'l1',type:'video'},{id:'l2',type:'text',html:'<h2>Дизайн починається з уваги</h2><p>Хороший інтерфейс допомагає людині зосередитися на головному. Не на кнопках, панелях чи налаштуваннях — на тому, заради чого вона сюди прийшла.</p><p>У цьому уроці розберемо, як <strong>візуальна ієрархія</strong> керує увагою та перетворює набір елементів на зрозумілу систему.</p><h3>Три рівні уваги</h3><ul><li><strong>Перший погляд.</strong> Що людина бачить одразу?</li><li><strong>Наступний крок.</strong> Куди її веде композиція?</li><li><strong>Деталі.</strong> Що стає помітним при уважному читанні?</li></ul>'},{id:'l3',type:'task',html:'<h3>Знайдіть головне</h3><p>Оберіть інтерфейс, яким користуєтесь щодня. Позначте три елементи, які першими привертають увагу. Чи відповідають вони головній задачі користувача?</p>'}];
export function App({initialPage}){const[page,setPage]=useState(initialPage||(()=>{if(typeof window==='undefined')return 'courses';return nav.some(n=>n[0]===window.location.hash.slice(1))?window.location.hash.slice(1):'courses'})()),[lang,setLang]=useState('uk'),[drawer,setDrawer]=useState(false),[courses,setCourses]=useState(fixtureCourses),[users,setUsers]=useState(fixtureUsers),[reports,setReports]=useState(fixtureReports),[refunds,setRefunds]=useState(fixtureRefunds),[selectedCourse,setSelectedCourse]=useState(fixtureCourses[0]),[modal,setModal]=useState(null),[toast,setToast]=useState(''),[working,setWorking]=useState(false),[search,setSearch]=useState(''),[filter,setFilter]=useState('All'),[role,setRole]=useState('All'),[range,setRange]=useState('This month'),[tab,setTab]=useState('Overview'),[form,setForm]=useState({title:'',description:'',price:'',email:''}),[errors,setErrors]=useState({}),[sections,setSections]=useState(lessonInitial),[lessonTitle,setLessonTitle]=useState('Візуальна ієрархія'),[preview,setPreview]=useState(false),[dirty,setDirty]=useState(false),[grants,setGrants]=useState([{id:'g1',email:'anna.koval@example.com',date:'12.10.2026'}]);const timer=useRef(),focusPage=useRef();const t=x=>lang==='uk'?(uk[x]||x):x;useEffect(()=>()=>clearTimeout(timer.current),[]);useEffect(()=>{const onHash=()=>{const v=window.location.hash.slice(1);if(nav.some(n=>n[0]===v)){setPage(v);setSearch('');setFilter('All');setRole('All')}};window.addEventListener('hashchange',onHash);return()=>window.removeEventListener('hashchange',onHash)},[]);useEffect(()=>{document.documentElement.lang=lang},[lang]);function notify(x){setToast(x);clearTimeout(timer.current);timer.current=setTimeout(()=>setToast(''),4500)}function navigate(v){setPage(v);window.history.replaceState(null,'','#'+v);setSearch('');setFilter('All');setRole('All');setTab('Overview');setDrawer(false);requestAnimationFrame(()=>focusPage.current?.focus())}function show(m){setErrors({});setModal(m)}function confirm(title,description,action,destructive=false){show({type:'confirm',title,description,action,destructive})}function run(action,message){setWorking(true);setTimeout(()=>{action();setWorking(false);setModal(null);notify(message)},450)}function exportCSV(){const rows=page==='users'?users:courses;const keys=page==='users'?['name','email','role','status']:['name','status','students','price'];const csv='\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=page+'.csv';a.click();URL.revokeObjectURL(url);notify(lang==='uk'?'CSV завантажено':'CSV downloaded')}const money=v=>new Intl.NumberFormat(lang==='uk'?'uk-UA':'en-US',{maximumFractionDigits:0}).format(v);const status=s=><Pill kind={statusKind[s]}>{t(s)}</Pill>;const editCourse=c=>{setSelectedCourse(c);navigate('course')};const navContent=<><a className="admin-brand" href="#courses" onClick={e=>{e.preventDefault();navigate('courses')}}><span className="brand-symbol"><Icon name="courses"/></span><span>course<span className="brand-muted">space</span></span></a><div className="admin-nav-label">WORKSPACE <Pill>ADMIN</Pill></div><nav aria-label={t('Navigation')}>{nav.map(([key,label,icon])=><Button key={key} className={'admin-nav-item '+(page===key?'is-current':'')} aria-current={page===key?'page':undefined} onPress={()=>navigate(key)}><Icon name={icon}/><span>{t(label)}</span>{key==='reports'&&<small>{reports.filter(r=>r.status==='Open').length}</small>}{key==='refunds'&&<small>{refunds.filter(r=>r.status==='Pending').length}</small>}</Button>)}</nav><div className="sidebar-reference"><span className="reference-light"/><span>{t('Reference prototype')}<small>{t('Demo data')} · React Aria</small></span></div><div className="sidebar-footer"><span className="admin-avatar">ОК</span><span>Олена Коваль<small>{t('Admin')}</small></span><Icon name="settings"/></div></>;
function filters(placeholder,statuses,extra){return <div className="admin-filters"><div className="search-field"><Icon name="search"/><input className="ui-input" type="search" aria-label={t(placeholder)} placeholder={t(placeholder)} value={search} onChange={e=>setSearch(e.target.value)}/></div><label className="filter-select"><span className="sr-only">{t('Status')}</span><select className="ui-input" value={filter} onChange={e=>setFilter(e.target.value)}><option value="All">{t('All statuses')}</option>{statuses.map(s=><option value={s} key={s}>{t(s)}</option>)}</select></label>{extra}<Button className="ui-button ui-button--secondary" onPress={exportCSV}><Icon name="download"/>{t('Export CSV')}</Button>{(search||filter!=='All'||role!=='All')&&<Button className="ui-button filter-reset" onPress={()=>{setSearch('');setFilter('All');setRole('All')}}>{t('Clear filters')}</Button>}</div>}
function createCourse(){setForm({title:'',description:'',price:'0',email:''});show({type:'create'})}function fieldError(key){let e='';if(key==='title'&&!form.title.trim())e=t('Title is required');if(key==='description'&&!form.description.trim())e=t('Description is required');if(key==='price'&&(!form.price.trim()||!Number.isFinite(Number(form.price))||Number(form.price)<0))e=t('Price must be zero or greater');if(key==='email'&&!/^\S+@\S+\.\S+$/.test(form.email))e=t('Enter a valid email');setErrors(v=>({...v,[key]:e}));return e}function validate(keys){const result=Object.fromEntries(keys.map(k=>[k,fieldError(k)]));return !Object.values(result).some(Boolean)}function updateForm(key,value){setForm(v=>({...v,[key]:value}))}function updateSection(id,data,parent,index){setSections(v=>v.map(s=>s.id===id?{...s,...data}:parent===s.id?{...s,children:s.children.map((c,i)=>i===index?c.map(child=>child.id===id?{...child,...data}:child):c)}:s));setDirty(true)}function addSection(type,parent,index){const item={id:crypto.randomUUID(),type,html:type==='task'?'<h3>Нове завдання</h3><p>Опишіть практику для студентів.</p>':'<p>Почніть писати тут…</p>',columns:2,children:[[],[]]};if(parent)setSections(v=>v.map(s=>s.id===parent?{...s,children:s.children.map((c,i)=>i===index?[...c,item]:c)}:s));else setSections(v=>[...v,item]);setDirty(true)}function palette(parent,index){return <div className={'lesson-editor-palette '+(parent?'is-nested':'')}>{Object.entries(sectionNames).filter(([key])=>!parent||['text','image','task'].includes(key)).map(([key,label])=>{const exists=key==='video'&&sections.some(s=>s.type==='video');return <Button key={key} className="ui-button ui-button--secondary palette-tile" aria-disabled={exists||undefined} onPress={()=>!exists&&addSection(key,parent,index)}><Icon name={key}/><strong>{t(label)}</strong><small>{exists?(lang==='uk'?'Вже в уроці':'Already added'):(lang==='uk'?{text:'Ідеї та пояснення',video:'Один блок на урок',image:'Ілюстрації й схеми',row:'2–3 колонки',task:'Практика для студентів'}[key]:{text:'Ideas & explanations',video:'One block per lesson',image:'Visuals & diagrams',row:'2–3 columns',task:'Student practice'}[key])}</small><Icon name="plus"/></Button>})}</div>}
function sectionBody(s,parent,index){if(s.type==='text'||s.type==='task')return preview?<div className={'lesson-prose '+(s.type==='task'?'lesson-document-task':'')} dangerouslySetInnerHTML={{__html:s.html}}/>:<RichText html={s.html} task={s.type==='task'} t={t} onChange={html=>updateSection(s.id,{html},parent,index)}/>;if(s.type==='video')return <div className="lesson-editor-video"><span className="ui-icon-tile"><Icon name="video"/></span><span className="admin-eyebrow">{t('Video')}</span><h3>{lang==='uk'?'Побачити ієрархію в дії':'See hierarchy in action'}</h3><p>{lang==='uk'?'Відео підключається в налаштуваннях курсу':'Attach a video in course settings'}</p><Button className="ui-button ui-button--secondary" onPress={()=>{navigate('course');setTab('Video settings')}}>{t('Video settings')}<Icon name="arrow"/></Button></div>;if(s.type==='image')return <div className="lesson-editor-image">{s.src?<img src={s.src} alt={s.alt||''}/>:<Empty icon="image" title={t('Upload image')} description="PNG / JPG / WebP · 2 MB"/>}{!preview&&<><label className="ui-field">{t('Upload image')}<input className="ui-input lesson-editor-upload" type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>2*1024*1024){notify(lang==='uk'?'Оберіть PNG, JPG або WebP до 2 МБ':'Choose PNG, JPG or WebP under 2 MB');return}const r=new FileReader();r.onload=()=>updateSection(s.id,{src:r.result},parent,index);r.readAsDataURL(f)}}/></label><Field label={t('Alternative text')} value={s.alt||''} onChange={alt=>updateSection(s.id,{alt},parent,index)} hint={lang==='uk'?'Опишіть зміст для читачів екрану':'Describe the image for screen readers'}/></>}</div>;return <>{!preview&&<div className="column-settings"><span className="admin-eyebrow">{t('Columns')}</span>{[2,3].map(n=><Button className="ui-button ui-button--secondary" key={n} aria-pressed={s.columns===n} aria-disabled={n===2&&s.children[2]?.length>0||undefined} onPress={()=>{if(n===2&&s.children[2]?.length){notify(lang==='uk'?'Спочатку видаліть вміст третьої колонки':'Remove third-column content first');return}updateSection(s.id,{columns:n,children:n===3&&s.children.length===2?[...s.children,[]]:s.children})}}>{n}</Button>)}</div>}<div className="lesson-editor-columns" data-columns={s.columns}>{s.children.slice(0,s.columns).map((c,i)=><div className="lesson-editor-column" key={i}>{c.map(child=><div className="nested-section" key={child.id}>{sectionBody(child,s.id,i)}{!preview&&<Button className="ui-button ui-button--secondary" onPress={()=>confirm(t('Remove section'),t('Delete')+' '+t(sectionNames[child.type])+'?',()=>updateSection(s.id,{children:s.children.map((a,j)=>j===i?a.filter(x=>x.id!==child.id):a)}),true)}>{t('Delete')}</Button>}</div>)}{!preview&&palette(s.id,i)}</div>)}</div></>}
function pageContent(){switch(page){case'courses':{const rows=courses.filter(c=>(!search||c.name.toLowerCase().includes(search.toLowerCase()))&&(filter==='All'||c.status===filter));return <><PageHeader eyebrow="CONTENT MANAGEMENT" title={t('Courses')} description={lang==='uk'?'Керуйте курсами, доступами й публікаціями в одному місці.':'Manage courses, access and publications in one place.'} actions={<Button className="ui-button ui-button--primary" onPress={createCourse}><Icon name="plus"/>{t('Create course')}</Button>}/><div className="admin-summary-strip"><span><strong>{courses.length}</strong>{t('Courses')}</span><span><span className="summary-dot"/><strong>{courses.filter(c=>c.status==='Published').length}</strong>{t('Published')}</span><span><strong>{courses.filter(c=>c.status==='Draft').length}</strong>{t('Drafts')}</span></div>{filters('Search courses',['Published','Draft','Archived'])}<DataTable rows={rows} caption={t('Courses')} t={t} emptyAction={<Button className="ui-button ui-button--secondary" onPress={()=>{setSearch('');setFilter('All')}}>{t('Clear filters')}</Button>} columns={[{key:'name',label:'Course',render:c=><button className="table-course-link" onClick={()=>editCourse(c)}><span className={'course-cover cover-'+c.cover}><Icon name={c.icon}/></span><span><strong>{c.name}</strong><small>{c.lessons} {t('Lessons').toLowerCase()} · {c.category}</small></span></button>},{key:'status',label:'Status',render:c=>status(c.status)},{key:'students',label:'Students',numeric:true},{key:'price',label:'Price',numeric:true,render:c=><>{money(c.price)} <small>UAH</small></>},{key:'updated',label:'Updated'}]} actions={c=><><IconButton name="edit" label={t('Edit')+' · '+c.name} onPress={()=>editCourse(c)}/><IconButton name="eye" label={t('Preview')+' · '+c.name} onPress={()=>{editCourse(c);navigate('lesson');setPreview(true)}}/><IconButton name="delete" label={t('Delete')+' · '+c.name} destructive onPress={()=>confirm(t('Delete course'),c.name,()=>setCourses(v=>v.filter(x=>x.id!==c.id)),true)}/></>}/></>}
case'analytics':{const prior=range==='Last month';return <><PageHeader eyebrow="PLATFORM STATISTICS" title={t('Analytics')} description={lang==='uk'?'Повна картина того, як зростає ваша школа.':'A clear picture of how your school is growing.'} actions={<div className="ui-segmented">{['Last month','This month'].map(r=><Button key={r} className="ui-button ui-segment" aria-pressed={range===r} onPress={()=>setRange(r)}>{t(r)}</Button>)}</div>}/><div className="analytics-period"><Icon name="clock"/>{prior?'01.09 — 30.09.2026':'01.10 — 14.10.2026'}<Pill kind="info">{t('Demo data')}</Pill></div><div className="analytics-group"><div className="group-heading"><h2>{t('Platform')}</h2><span>{lang==='uk'?'Рух і результат':'Activity & results'}</span></div><div className="stat-grid"><Stat label={t('Revenue')} value={'UAH '+money(prior?6420:7560)} trend={prior?'+8.2%':'+17.8%'} icon="refunds"/><Stat label={lang==='uk'?'Зарахування':'Enrollments'} value={prior?'148':'186'} trend="+25.7%" icon="learners"/><Stat label={lang==='uk'?'Конверсія':'Conversion'} value={prior?'3.8%':'4.6%'} trend="+0.8 pp" icon="analytics"/></div><div className="ui-card ui-chart"><div className="chart-heading"><div><span className="admin-eyebrow">{t('Revenue')}</span><h3>{lang==='uk'?'Дохід за період':'Revenue over time'}</h3></div><span className="chart-legend"><span className="summary-dot"/>UAH</span></div><div className="chart-layout"><div className="chart-y"><span>3 000</span><span>2 000</span><span>1 000</span><span>0</span></div><div><svg viewBox="0 0 800 170" preserveAspectRatio="none" role="img" aria-label={lang==='uk'?'Демонстраційний графік: дохід зростає з 420 до 2840 гривень':'Demo chart: revenue rises from 420 to 2840 UAH'}><path className="chart-grid" d="M0 10H800M0 60H800M0 110H800M0 160H800"/><path className="chart-area" d={prior?'M0 155 60 150 120 126 180 138 240 110 300 102 360 128 420 93 480 104 540 65 600 78 660 45 720 52 800 35V170H0Z':'M0 150 60 140 120 145 180 112 240 118 300 97 360 107 420 74 480 89 540 49 600 61 660 28 720 34 800 14V170H0Z'}/><path className="chart-line" d={prior?'M0 155 60 150 120 126 180 138 240 110 300 102 360 128 420 93 480 104 540 65 600 78 660 45 720 52 800 35':'M0 150 60 140 120 145 180 112 240 118 300 97 360 107 420 74 480 89 540 49 600 61 660 28 720 34 800 14'}/></svg><div className="chart-x">{[1,4,7,10,14].map(d=><span key={d}>{d} {prior?'вер':'жов'}</span>)}</div></div></div></div></div><div className="analytics-group"><div className="group-heading"><h2>{t('People')}</h2><span>{lang==='uk'?'Навчання, що триває':'Learning in progress'}</span></div><div className="stat-grid"><Stat label={t('Users')} value={prior?'1 128':'1 284'} trend="+13.8%" icon="users"/><Stat label={t('Active')+' · '+t('Learners').toLowerCase()} value={prior?'312':'368'} trend="+17.9%" icon="learners"/><Stat label={lang==='uk'?'Завершили курс':'Course completions'} value={prior?'64':'82'} trend="+28.1%" icon="resolve"/></div></div><div className="analytics-group"><div className="group-heading"><h2>{t('Content')}</h2><span>{lang==='uk'?'Від ідеї до уроку':'From idea to lesson'}</span></div><div className="stat-grid"><Stat label={t('Courses')} value={String(courses.length)} icon="courses"/><Stat label={t('Lessons')} value="48" icon="lesson"/><Stat label={t('Drafts')} value={String(courses.filter(c=>c.status==='Draft').length)} icon="edit"/></div></div></>}
case'users':{const rows=users.filter(u=>(u.name+' '+u.email).toLowerCase().includes(search.toLowerCase())&&(filter==='All'||u.status===filter)&&(role==='All'||u.role===role));return <><PageHeader eyebrow="ACCOUNT ADMINISTRATION" title={t('Users')} description={lang==='uk'?'Люди, ролі та безпека доступу до платформи.':'People, roles and secure platform access.'} actions={<Pill kind="info">{users.length} {t('Users').toLowerCase()}</Pill>}/>{filters('Search users',['Active','Blocked'],<label className="filter-select"><span className="sr-only">{t('Role')}</span><select className="ui-input" value={role} onChange={e=>setRole(e.target.value)}><option value="All">{t('All roles')}</option>{['Admin','Instructor','Student'].map(r=><option value={r} key={r}>{t(r)}</option>)}</select></label>)}<DataTable rows={rows} t={t} caption={t('Users')} emptyAction={<Button className="ui-button ui-button--secondary" onPress={()=>{setSearch('');setFilter('All');setRole('All')}}>{t('Clear filters')}</Button>} columns={[{key:'email',label:'Email',render:u=><div className="person-cell"><span className="admin-avatar">{u.initials}</span><span><strong>{u.name}</strong><small className="email-text">{u.email}</small></span></div>},{key:'role',label:'Role',render:u=><span className="role-badge">{t(u.role)}</span>},{key:'status',label:'Status',render:u=>status(u.status)},{key:'updated',label:'Updated'}]} actions={u=><><IconButton name="block" label={t(u.status==='Blocked'?'Unblock':'Block')+' · '+u.name} onPress={()=>confirm(t(u.status==='Blocked'?'Unblock':'Block'),u.email,()=>setUsers(v=>v.map(x=>x.id===u.id?{...x,status:x.status==='Blocked'?'Active':'Blocked'}:x)),u.status!=='Blocked')}/><IconButton name="reset" label={t('Reset password')+' · '+u.name} onPress={()=>confirm(t('Reset password'),lang==='uk'?'Демонстрація: лист не буде надіслано.':'Demo: no email will be sent.',()=>{},false)}/><IconButton name="delete" label={t('Delete')+' · '+u.name} destructive onPress={()=>confirm(t('Delete'),u.email,()=>setUsers(v=>v.filter(x=>x.id!==u.id)),true)}/></>}/></>}
case'course':return <><PageHeader eyebrow="COURSE WORKSPACE" title={selectedCourse.name} description={lang==='uk'?'Відредагуйте деталі та підготуйте курс до публікації.':'Edit the details and prepare your course for publication.'} actions={<>{status(selectedCourse.status)}<Button className="ui-button ui-button--secondary" onPress={()=>{navigate('lesson');setPreview(true)}}><Icon name="eye"/>{t('Preview')}</Button></>}/><div className="ui-segmented course-tabs">{['Overview','Lessons','Video settings','Access'].map(x=><Button key={x} className="ui-button ui-segment" aria-pressed={tab===x} onPress={()=>setTab(x)}>{t(x)}</Button>)}</div>{tab==='Overview'?<CourseForm key={selectedCourse.id} course={selectedCourse} t={t} lang={lang} onSave={values=>{const c={...selectedCourse,...values};setCourses(v=>v.map(x=>x.id===c.id?c:x));setSelectedCourse(c);notify(t('Saved in this session'))}} onPublish={()=>confirm(t('Ready to publish?'),selectedCourse.name,()=>{setCourses(v=>v.map(x=>x.id===selectedCourse.id?{...x,status:'Published'}:x));setSelectedCourse(v=>({...v,status:'Published'}))})} onDelete={()=>confirm(t('Delete course'),selectedCourse.name,()=>{setCourses(v=>v.filter(x=>x.id!==selectedCourse.id));navigate('courses')},true)}/>:tab==='Lessons'?<section className="ui-card"><div className="card-heading"><h2>{t('Lessons')}</h2><Pill>MODULE 01</Pill></div>{['Вступ до дизайну','Візуальна ієрархія','Колір і контраст','Типографіка'].map((name,i)=><div className="course-lesson-row" key={name}><span className="lesson-counter">{String(i+1).padStart(2,'0')}</span><div><strong>{name}</strong><small>{i===1?t('Draft'):t('Published')}</small></div><Button className="ui-button ui-button--secondary" onPress={()=>{setLessonTitle(name);navigate('lesson');setPreview(false)}}>{t('Edit')}<Icon name="arrow"/></Button></div>)}</section>:tab==='Video settings'?<VideoForm t={t} onSave={()=>notify(t('Saved in this session'))}/>:<section className="ui-card"><div className="card-heading"><h2>{t('Access grants')}</h2><Button className="ui-button ui-button--secondary" onPress={()=>{setForm({email:''});show({type:'grant'})}}><Icon name="plus"/>{t('Add grant')}</Button></div>{grants.map(g=><div className="grant-row" key={g.id}><span><strong>{g.email}</strong><small>{g.date}</small></span><Pill kind="success">{t('Active')}</Pill><IconButton name="revoke" label={t('Revoke')+' · '+g.email} destructive onPress={()=>confirm(t('Revoke'),g.email,()=>setGrants(v=>v.filter(x=>x.id!==g.id)),true)}/></div>)}{!grants.length&&<Empty icon="users" title={t('Access grants')} description={lang==='uk'?'Надайте доступ за електронною адресою.':'Grant access using an email address.'}/>}</section>}</>;
case'lesson':return <section className="lesson-editor"><PageHeader eyebrow="LESSON DOCUMENT · MODULE 01 / 02" title={t('Lesson editor')} description={lang==='uk'?'Створіть урок, який хочеться читати.':'Create a lesson worth reading.'} actions={<><Button className="ui-button ui-button--secondary" onPress={()=>{setDirty(false);notify(t('Saved in this session'))}}>{t('Save draft')}</Button><Button className="ui-button ui-button--primary" onPress={()=>confirm(t('Ready to publish?'),lang==='uk'?'Зміни залишаються в цій сесії прототипу.':'Changes stay within this prototype session.',()=>{setDirty(false);setPreview(true)})}>{t('Publish')}<Icon name="arrow"/></Button></>}/><div className="lesson-editor-meta"><div className="ui-segmented">{['Editor','Preview'].map(x=><Button key={x} className="ui-button ui-segment" aria-pressed={preview===(x==='Preview')} onPress={()=>setPreview(x==='Preview')}><Icon name={x==='Editor'?'text':'eye'}/>{t(x)}</Button>)}</div><span className="lesson-save-status"><span className={dirty?'unsaved-dot':'saved-dot'}/>{t(dirty?'Changes are not saved':'Saved in this session')} · {sections.length}</span></div><div className="lesson-title-block"><label className="admin-eyebrow" htmlFor="lesson-title">{t('Name')}</label>{preview?<h2>{lessonTitle}</h2>:<input id="lesson-title" className="lesson-title-input" value={lessonTitle} onChange={e=>{setLessonTitle(e.target.value);setDirty(true)}}/>}<span>{selectedCourse.name} / Module 01</span></div><ol className={'lesson-editor-sections '+(preview?'lesson-document':'')}>{sections.map((s,i)=><li className="lesson-editor-section ui-card" key={s.id} data-type={s.type}>{!preview&&<div className="lesson-editor-section-bar"><div className="section-identity"><span className="future-handle" aria-hidden="true"><Icon name="drag"/></span><span className="ui-icon-tile"><Icon name={s.type}/></span><span className="lesson-editor-section-type">{t(sectionNames[s.type])}</span><small>{String(i+1).padStart(2,'0')}</small></div><div className="lesson-editor-section-actions">{[-1,1].map(delta=><IconButton key={delta} name={delta===-1?'up':'down'} label={t(delta===-1?'Move up':'Move down')+' · '+(i+1)} unavailable={i+delta<0||i+delta>=sections.length} onPress={()=>{setSections(v=>{const a=[...v];[a[i],a[i+delta]]=[a[i+delta],a[i]];return a});setDirty(true)}}/>)}<IconButton name="delete" label={t('Remove section')+' · '+(i+1)} destructive onPress={()=>confirm(t('Remove section'),t(sectionNames[s.type]),()=>{setSections(v=>v.filter(x=>x.id!==s.id));setDirty(true)},true)}/></div></div>}{sectionBody(s)}</li>)}</ol>{!sections.length&&<Empty icon="lesson" title={t('Add section')} description={lang==='uk'?'Оберіть перший блок нижче.':'Choose the first block below.'}/>} {!preview&&<fieldset className="lesson-editor-add"><legend><Icon name="plus"/>{t('Add section')}</legend><p>{lang==='uk'?'Оберіть блок, щоб продовжити урок':'Choose a block to continue your lesson'}</p>{palette()}</fieldset>}</section>;
case'learners':{const rows=fixtureLearners.filter(l=>(l.name+' '+l.email).toLowerCase().includes(search.toLowerCase())&&(filter==='All'||l.status===filter));return <><PageHeader eyebrow="LEARNING EXPERIENCE" title={t('Learners')} description={lang==='uk'?'Допомагайте студентам рухатися від першого уроку до результату.':'Help students move from their first lesson to a real outcome.'} actions={<Pill kind="info">{fixtureLearners.length} {t('Learners').toLowerCase()}</Pill>}/>{filters('Search learners',['Active','Blocked'])}<div className="learner-grid">{rows.map(l=><article className="ui-card learner-card" key={l.id}><div className="learner-header"><div className="person-cell"><span className="admin-avatar">{l.initials}</span><div><h2>{l.name}</h2><small>{l.email}</small></div></div>{status(l.status)}</div><div className="learner-enrollment"><span className="admin-eyebrow">{t('Enrollment')}</span><a href="#course" onClick={e=>{e.preventDefault();editCourse(courses.find(c=>c.id===l.courseId)||fixtureCourses[0])}}>{l.course}<Icon name="arrow"/></a></div><div className="learner-progress-label"><span>{t('Progress')}</span><strong>{l.progress}%</strong></div><div className="ui-progress" role="progressbar" aria-label={t('Progress')+' · '+l.name} aria-valuenow={l.progress} aria-valuemin={0} aria-valuemax={100}><span style={{inlineSize:l.progress+'%'}}/></div><div className="learner-meta"><span><Icon name="clock"/>{t('Last activity')}</span><strong>{l.last}</strong></div></article>)}</div>{!rows.length&&<section className="ui-card"><Empty title={t('No results')} description={t('Change your search or clear the filters.')} action={<Button className="ui-button ui-button--secondary" onPress={()=>{setSearch('');setFilter('All')}}>{t('Clear filters')}</Button>}/></section>}</>}
case'reports':{const rows=reports.filter(r=>filter==='All'||r.status===filter);return <><PageHeader eyebrow="SAFETY & TRUST" title={t('Reports')} description={lang==='uk'?'Розглядайте звернення уважно. Безпечне навчання починається тут.':'Review each report carefully. Safe learning starts here.'} actions={<Pill kind="info">{reports.filter(r=>r.status==='Open').length} {t('Open').toLowerCase()}</Pill>}/><QueueFilter value={filter} onChange={setFilter} items={['All','Open','Resolved']} t={t}/><div className="queue-grid">{rows.map(r=><article className="ui-card report-card" key={r.id}><div className="queue-heading"><span className="ui-icon-tile"><Icon name="reports"/></span><div><span className="admin-eyebrow">{r.id} · {r.date}</span><h2>{r.subject}</h2></div>{status(r.status)}</div><p className="report-body">{r.description}</p><div className="report-details"><div><span>{lang==='uk'?'Автор звернення':'Reported by'}</span><strong>{r.person}</strong></div><div><span>{t('Course')}</span><strong>{r.course}</strong></div><div><span>{lang==='uk'?'Учасник':'Participant'}</span><strong>{r.participant}</strong></div></div><div className="queue-actions"><Button className="ui-button ui-button--secondary" onPress={()=>show({type:'details',title:r.subject,description:r.description,record:r})}><Icon name="eye"/>{t('Details')}</Button><Button className="ui-button ui-button--secondary" aria-disabled={r.status==='Resolved'||undefined} onPress={()=>r.status!=='Resolved'&&confirm(t('Resolve'),r.subject,()=>setReports(v=>v.map(x=>x.id===r.id?{...x,status:'Resolved'}:x)))}><Icon name="resolve"/>{t('Resolve')}</Button></div></article>)}</div>{!rows.length&&<section className="ui-card"><Empty icon="reports" title={t('No results')} description={t('Change your search or clear the filters.')} action={<Button className="ui-button ui-button--secondary" onPress={()=>setFilter('All')}>{t('All')}</Button>}/></section>}</>}
case'refunds':{const rows=refunds.filter(r=>filter==='All'||r.status===filter);return <><PageHeader eyebrow="PAYMENTS & REFUNDS" title={t('Refunds')} description={lang==='uk'?'Прозорий процес повернення — частина довіри до вашої школи.':'A transparent refund process builds trust in your school.'} actions={<Pill kind="info">{refunds.filter(r=>r.status==='Pending').length} {t('Pending').toLowerCase()}</Pill>}/><QueueFilter value={filter} onChange={setFilter} items={['All','Pending','Refunded','Declined']} t={t}/>{!rows.length?<section className="ui-card refund-empty"><Empty icon="refunds" title={t('No pending refunds')} description={t('The queue is clear. New requests will appear here.')} action={<Button className="ui-button ui-button--secondary" onPress={()=>{setRefunds(fixtureRefunds);setFilter('All')}}><Icon name="plus"/>{t('Show example requests')}</Button>}/></section>:<div className="queue-grid">{rows.map(r=><article className="ui-card refund-card" key={r.id}><div className="queue-heading"><span className="ui-icon-tile"><Icon name="refunds"/></span><div><span className="admin-eyebrow">{r.id} · {r.date}</span><h2>{r.person}</h2></div>{status(r.status)}</div><div className="refund-summary"><div><span>{t('Course')}</span><strong>{r.course}</strong><small>{r.email}</small></div><strong className="refund-amount">{money(r.amount)} <span>UAH</span></strong></div><p className="report-body">{r.reason}</p><div className="queue-actions"><span className="queue-policy">{lang==='uk'?'Демонстрація · кошти не переміщуються':'Demo · no funds are transferred'}</span><Button className="ui-button ui-button--secondary" aria-disabled={r.status!=='Pending'||undefined} onPress={()=>r.status==='Pending'&&confirm(t('Revoke'),r.person+' · '+r.course,()=>setRefunds(v=>v.map(x=>x.id===r.id?{...x,status:'Declined'}:x)),true)}><Icon name="revoke"/>{t('Revoke')}</Button><Button className="ui-button ui-button--secondary" aria-disabled={r.status!=='Pending'||undefined} onPress={()=>r.status==='Pending'&&confirm(t('Resolve'),money(r.amount)+' UAH · '+r.person,()=>setRefunds(v=>v.map(x=>x.id===r.id?{...x,status:'Refunded'}:x)),true)}><Icon name="resolve"/>{t('Resolve')}</Button></div></article>)}</div>}<div className="queue-example-tools"><Button className="ui-button" onPress={()=>{setRefunds([]);setFilter('Pending')}}>{lang==='uk'?'Показати порожній стан':'Show empty state'}</Button><Button className="ui-button" onPress={()=>{setRefunds(fixtureRefunds);setFilter('All')}}>{t('Reset demo')}</Button></div></>}
}}
return <div className="admin-shell"><aside className="admin-sidebar">{navContent}</aside><div className="admin-canvas"><header className="admin-header"><div className="mobile-nav-trigger"><IconButton name="menu" label={t('Navigation')} onPress={()=>setDrawer(true)}/></div><div className="admin-header-breadcrumb"><span>{t('Administration')}</span><Icon name="arrow"/><strong>{t(nav.find(n=>n[0]===page)?.[1]||'Courses')}</strong></div><div className="admin-header-right"><span className="header-user">Олена Коваль</span><div className="ui-segmented language-switch" aria-label={t('Language')}>{['uk','en'].map(l=><Button key={l} className="ui-button ui-segment" aria-label={l==='uk'?'Українська':'English'} aria-pressed={lang===l} onPress={()=>setLang(l)}>{l==='uk'?'UA':'EN'}</Button>)}</div><IconButton name="logout" label={t('Sign out')} onPress={()=>show({type:'details',title:t('Sign out'),description:lang==='uk'?'Це прототип без облікового запису. Автентифікація не підключена.':'This prototype has no account session. Authentication is not connected.'})}/></div></header><div className="prototype-banner"><span className="prototype-mark"/><span>{t('Reference prototype')} <span className="prototype-description">· {lang==='uk'?'демодані, дії в межах сесії':'demo data, session-only interactions'}</span></span><Button className="ui-button" onPress={()=>show({type:'spec',title:t('Design specification')})}>{t('Design specification')}<Icon name="arrow"/></Button></div><main className="admin-content" ref={focusPage} tabIndex={-1}>{pageContent()}<footer className="admin-footer"><span>COURSESPACE <span> / </span> ADMIN WORKSPACE</span><span>{t('Demo data')} · 2026</span></footer></main></div><ModalOverlay isOpen={drawer} onOpenChange={setDrawer} isDismissable className="drawer-overlay"><Modal className="admin-drawer"><Dialog aria-label={t('Navigation')}><div className="drawer-close"><IconButton name="revoke" label={t('Close')} onPress={()=>setDrawer(false)}/></div>{navContent}</Dialog></Modal></ModalOverlay><ModalBox open={!!modal} onClose={()=>!working&&setModal(null)} title={modal?.title||t(modal?.type==='create'?'New course':modal?.type==='grant'?'Add grant':'Confirm')} footer={modal?.type==='confirm'?<><Button className="ui-button ui-button--secondary" aria-disabled={working||undefined} onPress={()=>!working&&setModal(null)}>{t('Cancel')}</Button><Button className={'ui-button '+(modal.destructive?'ui-button--danger':'ui-button--primary')} aria-disabled={working||undefined} onPress={()=>!working&&run(modal.action,t('Saved in this session'))}>{working?<><span className="ui-spinner"/>{lang==='uk'?'Застосування…':'Applying…'}</>:t('Confirm')}</Button></>:modal?.type==='create'||modal?.type==='grant'?<><Button className="ui-button ui-button--secondary" onPress={()=>setModal(null)}>{t('Cancel')}</Button><Button className="ui-button ui-button--primary" aria-disabled={working||undefined} onPress={()=>{if(working||!validate(modal.type==='create'?['title','description','price']:['email']))return;const isCreate=modal.type==='create';run(()=>{if(isCreate){const c={id:crypto.randomUUID(),name:form.title,description:form.description,price:Number(form.price),status:'Draft',students:0,lessons:0,updated:'14.10.2026',category:'Новий курс',cover:'blue',icon:'course'};setCourses(v=>[c,...v])}else setGrants(v=>[...v,{id:crypto.randomUUID(),email:form.email,date:'14.10.2026'}])},t('Saved in this session'))}}>{working?<><span className="ui-spinner"/>{lang==='uk'?'Збереження…':'Saving…'}</>:t(modal.type==='create'?'Create':'Add grant')}</Button></>:null}>{modal?.type==='confirm'||modal?.type==='details'?<><p>{modal.description}</p>{modal.record&&<div className="ui-card"><strong>{modal.record.person}</strong><p>{modal.record.course}</p><Pill kind={statusKind[modal.record.status]}>{t(modal.record.status)}</Pill></div>}</>:modal?.type==='create'||modal?.type==='grant'?<div className="modal-form">{Object.values(errors).some(Boolean)&&<div className="ui-error-summary" role="alert"><strong>{t('Fix the highlighted fields')}</strong><ul>{Object.values(errors).filter(Boolean).map(e=><li key={e}>{e}</li>)}</ul></div>}{(modal.type==='create'?['title','description','price']:['email']).map(key=><Field key={key} label={t({title:'Course title',description:'Description',price:'Price',email:'Email'}[key])+(key==='price'?' · UAH':'')} value={form[key]} onChange={v=>updateForm(key,v)} onBlur={()=>fieldError(key)} error={errors[key]} textarea={key==='description'} type={key==='price'?'number':key==='email'?'email':'text'}/>)}</div>:modal?.type==='spec'?<DesignSpec lang={lang}/>:null}</ModalBox><div className={'ui-toast '+(toast?'is-visible':'')} role="status" aria-live="polite">{toast&&<><Icon name="resolve"/>{toast}</>}</div></div>}
function QueueFilter({value,onChange,items,t}){return <div className="queue-filter ui-segmented">{items.map(x=><Button key={x} className="ui-button ui-segment" aria-pressed={value===x} onPress={()=>onChange(x)}>{t(x)}</Button>)}</div>}
function Stat({label,value,trend,icon}){return <article className="ui-card ui-stat"><div><span>{label}</span><span className="ui-icon-tile"><Icon name={icon}/></span></div><strong>{value}</strong><small>{trend?<><span>{trend}</span> vs. previous period</>:<span>PLATFORM CONTENT</span>}</small></article>}
function CourseForm({course,t,lang,onSave,onPublish,onDelete}){const[values,setValues]=useState({name:course.name,description:course.description||'Навчіться будувати зрозумілі інтерфейси: від візуальної ієрархії до готового прототипу.',price:String(course.price)}),[errors,setErrors]=useState({}),[saved,setSaved]=useState(false);const validate=k=>{const err=k==='name'&&!values.name.trim()?t('Title is required'):k==='description'&&!values.description.trim()?t('Description is required'):k==='price'&&(!values.price.trim()||Number(values.price)<0||!Number.isFinite(Number(values.price)))?t('Price must be zero or greater'):'';setErrors(v=>({...v,[k]:err}));return err};return <div className="course-form-layout"><form className="ui-card course-details-form" noValidate onSubmit={e=>{e.preventDefault();const bad=['name','description','price'].map(validate).some(Boolean);if(!bad){onSave({...values,price:Number(values.price)});setSaved(true)}}}><div className="card-heading"><h2>{t('Details')}</h2><Icon name="course"/></div>{Object.values(errors).some(Boolean)&&<div role="alert" className="ui-error-summary"><strong>{t('Fix the highlighted fields')}</strong><ul>{Object.values(errors).filter(Boolean).map(x=><li key={x}>{x}</li>)}</ul></div>}{['name','description','price'].map(k=><Field key={k} label={t({name:'Course title',description:'Description',price:'Price'}[k])+(k==='price'?' · UAH':'')} value={values[k]} textarea={k==='description'} type={k==='price'?'number':'text'} onChange={v=>{setValues(s=>({...s,[k]:v}));setSaved(false)}} onBlur={()=>validate(k)} error={errors[k]}/>) }<div className="form-footer"><span>{saved?t('Saved in this session'):lang==='uk'?'Зміни не публікуються автоматично':'Changes are not published automatically'}</span><Button type="submit" className="ui-button ui-button--primary">{t('Save changes')}</Button></div></form><div className="course-side-panels"><section className="ui-card"><div className="card-heading"><h2>{t('Status')}</h2><Pill kind={statusKind[course.status]}>{t(course.status)}</Pill></div><p>{lang==='uk'?'Публікуйте курс після перевірки змісту, відео та доступів.':'Publish after reviewing content, videos and access.'}</p><Button className="ui-button ui-button--primary" onPress={onPublish}>{t('Publish')}<Icon name="arrow"/></Button></section><section className="ui-card course-mini-stats"><div><span>{t('Lessons')}</span><strong>{course.lessons}</strong></div><div><span>{t('Students')}</span><strong>{course.students}</strong></div><div><span>{t('Updated')}</span><strong>{course.updated}</strong></div></section><section className="ui-card danger-panel"><span className="admin-eyebrow">{lang==='uk'?'НЕБЕЗПЕЧНА ЗОНА':'DANGER ZONE'}</span><h2>{t('Delete course')}</h2><p>{lang==='uk'?'Курс і його структура будуть видалені з цієї демосесії.':'The course and its structure will be removed from this demo session.'}</p><Button className="ui-button ui-button--danger" onPress={onDelete}><Icon name="delete"/>{t('Delete course')}</Button></section></div></div>}
function VideoForm({t,onSave}){const[url,setUrl]=useState(''),[error,setError]=useState('');return <form className="ui-card video-settings-form" onSubmit={e=>{e.preventDefault();if(!/^https?:\/\//i.test(url)){setError('URL: https://…');return}setError('');onSave()}}><div className="card-heading"><h2>{t('Video settings')}</h2><Icon name="video"/></div><Field label="Video URL" value={url} onChange={setUrl} onBlur={()=>setError(url&&!/^https?:\/\//i.test(url)?'URL: https://…':'')} error={error} hint="Reference prototype · metadata only, no streaming backend"/><Button type="submit" className="ui-button ui-button--primary">{t('Save changes')}</Button></form>}
function DesignSpec({lang}){return <div className="design-spec"><Pill kind="info">React + React Aria + plain CSS</Pill><p>{lang==='uk'?'Один shell, одна система карток, один шаблон таблиць. Дані демонстраційні; API та production shell не підключено.':'One shell, one card system, one table pattern. Demo data; no production shell or API is connected.'}</p><h3>Shared primitives</h3><ul><li><code>.admin-shell</code> · labeled navigation + mobile modal drawer.</li><li><code>.ui-table</code> · sticky inline-end actions; labeled stacked cards below 52rem.</li><li><code>.ui-card</code> · background + hairline + shadow; no lighter card fill.</li><li><code>.ui-field</code> · labels, blur validation, error summary, retained values.</li><li><code>.ui-pill</code> · unified semantic statuses.</li><li><code>.ui-button</code> · 44px, focus, pressed, unavailable no-op, loading; icon actions have tooltips.</li></ul><h3>Contrast</h3><p>Original primary gradient: white text 3.25:1 at lightest stop, 4.50:1 at darkest stop. Primary labels: 1.1875rem / 750 (large bold). Hover keeps the same gradient. Normal text never uses solid brand blue as a fill.</p><a href="admin-restyle-sources.zip" download className="ui-button ui-button--secondary"><Icon name="download"/>{lang==='uk'?'Вихідний код і специфікація':'Sources & specification'}</a><h3>New tokens</h3><ul><li><code>--space-admin-sidebar: 15.5rem</code></li><li><code>--space-admin-canvas: 76rem</code></li><li><code>--space-dialog: 36rem</code></li><li><code>--space-icon: 1.25rem</code></li><li><code>--space-prose-measure: 65ch</code></li><li><code>--space-prose-min: 12rem</code></li><li><code>--space-tile-min: 9rem</code></li><li><code>--space-border: 1px</code></li><li><code>--space-focus-ring / --space-focus-offset: 3px</code></li><li><code>--space-callout-rule: .25rem</code></li><li><code>--color-modal-backdrop</code> · background 85% / transparent</li><li><code>--color-forced-background / text / control / control-text / focus / unavailable</code> · Canvas / CanvasText / ButtonFace / ButtonText / Highlight / GrayText</li></ul><h3>Translation notes</h3><p>Translate these rules onto your existing shell. This reference uses the class names supplied in the brief; it cannot modify the unseen production DOM. No parallel typography tokens, no disabled nav/reorder controls, no localStorage. Browser checks for 375px, 200% text zoom and forced colors are still required before production use.</p><h3>Rationale</h3><p>One navigation removes the duplicate rail. Cards restore section hierarchy. Sticky actions and stacked mobile rows keep decisions close to identifiers. Learners get separated enrollment and status zones; safety and payments become structured queues. The lesson canvas uses the same surfaces, typography and controls.</p></div>}

